// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { DropdownMenu } from "@/registry/erbium/ui/dropdown-menu";

import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import {\n  DropdownMenu,\n  DropdownMenuTrigger,\n  DropdownMenuContent,\n  DropdownMenuItem,\n} from \"@/registry/erbium/ui/dropdown-menu\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nconst Example = (args: {\n  side: \"top\" | \"right\" | \"bottom\" | \"left\";\n  align: \"start\" | \"center\" | \"end\";\n  defaultOpen: boolean;\n}) => (\n  <DropdownMenu key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>\n    <DropdownMenuTrigger render={<Button variant=\"outline\">Open menu</Button>} />\n    <DropdownMenuContent side={args.side} align={args.align}>\n      <DropdownMenuItem>Profile</DropdownMenuItem>\n      <DropdownMenuItem>Settings</DropdownMenuItem>\n    </DropdownMenuContent>\n  </DropdownMenu>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/dropdown-menu-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import RadioGroupExample from "./variants/radio-group";

const RadioGroupSource = "import ExampleDropdownMenuRadioGroup from \"../examples/dropdown-menu-radio-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleDropdownMenuRadioGroup />\n  </div>\n);\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import { DropdownMenuBasic } from \"../examples/upstream/dropdown-menu-basic\";\n\nconst Example = () => <DropdownMenuBasic />;\n\nexport default Example;\n";

import SubmenuExample from "./variants/submenu";

const SubmenuSource = "import { DropdownMenuSubmenu } from \"../examples/upstream/dropdown-menu-submenu\";\n\nconst Example = () => <DropdownMenuSubmenu />;\n\nexport default Example;\n";

import ShortcutsExample from "./variants/shortcuts";

const ShortcutsSource = "import { DropdownMenuShortcuts } from \"../examples/upstream/dropdown-menu-shortcuts\";\n\nconst Example = () => <DropdownMenuShortcuts />;\n\nexport default Example;\n";

import IconsExample from "./variants/icons";

const IconsSource = "import { DropdownMenuIcons } from \"../examples/upstream/dropdown-menu-icons\";\n\nconst Example = () => <DropdownMenuIcons />;\n\nexport default Example;\n";

import CheckboxesExample from "./variants/checkboxes";

const CheckboxesSource = "import { DropdownMenuCheckboxes } from \"../examples/upstream/dropdown-menu-checkboxes\";\n\nconst Example = () => <DropdownMenuCheckboxes />;\n\nexport default Example;\n";

import CheckboxesIconsExample from "./variants/checkboxes-icons";

const CheckboxesIconsSource = "import { DropdownMenuCheckboxesIcons } from \"../examples/upstream/dropdown-menu-checkboxes-icons\";\n\nconst Example = () => <DropdownMenuCheckboxesIcons />;\n\nexport default Example;\n";

import RadioIconsExample from "./variants/radio-icons";

const RadioIconsSource = "import { DropdownMenuRadioIcons } from \"../examples/upstream/dropdown-menu-radio-icons\";\n\nconst Example = () => <DropdownMenuRadioIcons />;\n\nexport default Example;\n";

import ErrorVariantExample from "./variants/error-variant";

const ErrorVariantSource = "import { DropdownMenuError } from \"../examples/upstream/dropdown-menu-error\";\n\nconst Example = () => <DropdownMenuError />;\n\nexport default Example;\n";

import AvatarExample from "./variants/avatar";

const AvatarSource = "import { DropdownMenuAvatar } from \"../examples/upstream/dropdown-menu-avatar\";\n\nconst Example = () => <DropdownMenuAvatar />;\n\nexport default Example;\n";

import ComplexExample from "./variants/complex";

const ComplexSource = "import { DropdownMenuComplex } from \"../examples/upstream/dropdown-menu-complex\";\n\nconst Example = () => <DropdownMenuComplex />;\n\nexport default Example;\n";

const meta = {
  title: "UI/Dropdown Menu",
  component: DropdownMenu,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "Displays a menu to the user — such as a set of actions or functions — triggered by a button.\n\n**Import:** `@/registry/erbium/ui/dropdown-menu`\n\n## Usage\n\n```tsx\nimport { Button } from \"@/registry/erbium/ui/button\"\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuGroup,\n  DropdownMenuItem,\n  DropdownMenuLabel,\n  DropdownMenuSeparator,\n  DropdownMenuTrigger,\n} from \"@/registry/erbium/ui/dropdown-menu\"\nimport {{ Button }} from \"@/registry/erbium/ui/button\"\n```\n\n```tsx\n<DropdownMenu>\n  <DropdownMenuTrigger render={<Button variant=\"outline\" />}>Open</DropdownMenuTrigger>\n  <DropdownMenuContent>\n    <DropdownMenuGroup>\n      <DropdownMenuLabel>My Account</DropdownMenuLabel>\n      <DropdownMenuItem>Profile</DropdownMenuItem>\n      <DropdownMenuItem>Billing</DropdownMenuItem>\n    </DropdownMenuGroup>\n    <DropdownMenuSeparator />\n    <DropdownMenuGroup>\n      <DropdownMenuItem>Team</DropdownMenuItem>\n      <DropdownMenuItem>Subscription</DropdownMenuItem>\n    </DropdownMenuGroup>\n  </DropdownMenuContent>\n</DropdownMenu>\n```\n\n## Composition\n\nUse the following composition to build a `DropdownMenu`:\n\n```text\nDropdownMenu\n├── DropdownMenuTrigger\n└── DropdownMenuContent\n    ├── DropdownMenuGroup\n    │   ├── DropdownMenuLabel\n    │   ├── DropdownMenuItem\n    │   └── DropdownMenuItem\n    ├── DropdownMenuSeparator\n    ├── DropdownMenuGroup\n    │   ├── DropdownMenuLabel\n    │   ├── DropdownMenuCheckboxItem\n    │   └── DropdownMenuCheckboxItem\n    ├── DropdownMenuSeparator\n    ├── DropdownMenuGroup\n    │   ├── DropdownMenuLabel\n    │   └── DropdownMenuRadioGroup\n    │       ├── DropdownMenuRadioItem\n    │       └── DropdownMenuRadioItem\n    └── DropdownMenuSub\n        ├── DropdownMenuSubTrigger\n        └── DropdownMenuSubContent\n            └── DropdownMenuGroup\n                ├── DropdownMenuLabel\n                ├── DropdownMenuItem\n                └── DropdownMenuItem\n```",
      },
    },
  },
} satisfies Meta<typeof DropdownMenu>;

export default { ...meta,  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

