export const Icons: Story = {
  parameters: {
    docs: {
      description: { story: "Combine icons with labels for quick scanning." },
      source: { code: IconsSource },
    },
  },
  render: IconsExample,
};

export const Checkboxes: Story = {
  parameters: {
    docs: {
