      source: { code: CheckboxesSource },
    },
  },
  render: CheckboxesExample,
};

export const CheckboxesIcons: Story = {
  parameters: {
    docs: {
      description: { story: "Add icons to checkbox items." },
      source: { code: CheckboxesIconsSource },
    },
  },
  render: CheckboxesIconsExample,
