export const ErrorVariant: Story = {
  name: "Error",
  parameters: {
    docs: {
      description: { story: "Use `variant=\"error\"` for irreversible actions." },
      source: { code: ErrorVariantSource },
    },
  },
  render: ErrorVariantExample,
